#[test]
fn bindgen_test_layout_SDL_Cursor() {
    assert_eq!(
        ::std::mem::size_of::<SDL_Cursor>(),
        56usize,
        concat!("Size of: ", stringify!(SDL_Cursor))
    );
    assert_eq!(
        ::std::mem::align_of::<SDL_Cursor>(),
        8usize,
        concat!("Alignment of ", stringify!(SDL_Cursor))
    );
    assert_eq!(
        unsafe {
            &(*(::std::ptr::null::<SDL_Cursor>())).area as *const _
                as usize
        },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(SDL_Cursor),
            "::",
            stringify!(area)
        )
    );
    assert_eq!(
        unsafe {
            &(*(::std::ptr::null::<SDL_Cursor>())).hot_x as *const _
                as usize
        },
        8usize,
        concat!(
            "Offset of field: ",
            stringify!(SDL_Cursor),
            "::",
            stringify!(hot_x)
        )
    );
    assert_eq!(
        unsafe {
            &(*(::std::ptr::null::<SDL_Cursor>())).hot_y as *const _
                as usize
        },
        10usize,
        concat!(
            "Offset of field: ",
            stringify!(SDL_Cursor),
            "::",
            stringify!(hot_y)
        )
    );
    assert_eq!(
        unsafe {
            &(*(::std::ptr::null::<SDL_Cursor>())).data as *const _
                as usize
        },
        16usize,
        concat!(
            "Offset of field: ",
            stringify!(SDL_Cursor),
            "::",
            stringify!(data)
        )
    );
    assert_eq!(
        unsafe {
            &(*(::std::ptr::null::<SDL_Cursor>())).mask as *const _
                as usize
        },
        24usize,
        concat!(
            "Offset of field: ",
            stringify!(SDL_Cursor),
            "::",
            stringify!(mask)
        )
    );
    assert_eq!(
        unsafe {
            &(*(::std::ptr::null::<SDL_Cursor>())).save as *const _
                as usize
        },
        32usize,
        concat!(
            "Offset of field: ",
            stringify!(SDL_Cursor),
            "::",
            stringify!(save)
        )
    );
    assert_eq!(
        unsafe {
            &(*(::std::ptr::null::<SDL_Cursor>())).wm_cursor as *const _
                as usize
        },
        48usize,
        concat!(
            "Offset of field: ",
            stringify!(SDL_Cursor),
            "::",
            stringify!(wm_cursor)
        )
    );
}
